def _as_quantities(*args):
    """Convert arguments to Quantity (or raise NotImplentedError)."""
    from astropy.units import Quantity

    try:
        # Note: this should keep the dtype the same
        return tuple(
            Quantity(a, copy=COPY_IF_NEEDED, subok=True, dtype=None) for a in args
        )
    except Exception:
        # If we cannot convert to Quantity, we should just bail.
        raise NotImplementedError


def _iterable_helper(*args, out=None, **kwargs):
    """Prepare an iterable of values that have to share one unit."""
    from astropy.units import Quantity

    if not args:
        # Let numpy produce its usual error for an empty input sequence.
        return (), kwargs, dimensionless_unscaled, out

    quantities = _as_quantities(*args)

    # An ordinary array at the start of a sequence should not force all later
    # quantities to be dimensionless.  Conversely, an explicitly supplied
    # dimensionless Quantity is meaningful and remains authoritative.
    unit_source = next(
        (
            quantity
            for original, quantity in zip(args, quantities)
            if isinstance(original, Quantity) or hasattr(original, "unit")
        ),
        quantities[0],
    )
    unit = unit_source.unit
    arrays = tuple(unit_source._to_own_unit(arg) for arg in args)

    if out is not None:
        kwargs["out"] = _quantity_out_as_array(out)

    return arrays, kwargs, unit, out

